// ZDO request/response differential against pinned zigbee-herdsman 11.2.0:
// bind/unbind (unicast/multicast), address requests, descriptors, LQI/binding/
// routing table requests, leave/permit-join, response payloads and status
// handling. Fixtures are generated by tools/oracle/generate-zdo-frames-pinned.mjs.

use serde::Deserialize;
use serde_json::Value;
use zigbee_apiarist::zspec::zdo::buffalo_zdo::BuffaloZdo;
use zigbee_apiarist::zspec::zdo::definition::clusters::ClusterId;

#[derive(Debug, Deserialize)]
struct Fixture {
    revision: String,
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
struct Case {
    name: String,
    op: String,
    #[serde(rename = "clusterId")]
    cluster_id: u16,
    args: Option<Vec<Value>>,
    #[serde(default)]
    overhead: bool,
    buffer: Option<String>,
    expected: Value,
}

fn bytes(hex: &str) -> Vec<u8> {
    (0..hex.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&hex[index..index + 2], 16).expect("hex"))
        .collect()
}
fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}
/// Upstream `undefined` object fields are omitted by JSON.stringify while the
/// Rust port represents them as `null`. Arrays keep their null placeholders
/// (e.g. `[status, undefined]`).
fn normalize(value: &Value) -> Value {
    match value {
        Value::Object(map) => Value::Object(
            map.iter()
                .filter(|(_, value)| !value.is_null())
                .map(|(key, value)| (key.clone(), normalize(value)))
                .collect(),
        ),
        Value::Array(items) => Value::Array(items.iter().map(normalize).collect()),
        other => other.clone(),
    }
}

#[test]
fn zdo_requests_and_responses_match_pinned_upstream() {
    let fixture: Fixture =
        serde_json::from_str(include_str!("fixtures/zdo-frames-pinned.json")).expect("fixture");
    assert_eq!(fixture.revision, "zigbee-herdsman 11.2.0");
    assert_eq!(fixture.cases.len(), 28);
    for case in &fixture.cases {
        match case.op.as_str() {
            "build_request" => {
                let args = case.args.clone().unwrap_or_default();
                let actual = BuffaloZdo::build_request(case.overhead, case.cluster_id, &args);
                assert_eq!(
                    hex(&actual),
                    case.expected.as_str().unwrap(),
                    "{}",
                    case.name
                );
            }
            "read_response" => {
                let buffer = bytes(case.buffer.as_deref().expect("buffer"));
                let actual = BuffaloZdo::read_response(case.overhead, case.cluster_id, &buffer);
                assert_eq!(
                    normalize(&actual),
                    normalize(&case.expected),
                    "{}",
                    case.name
                );
                // Status handling is derived from the same payload.
                let expected_status = case
                    .expected
                    .as_array()
                    .and_then(|items| items.first())
                    .and_then(Value::as_u64)
                    .unwrap_or(0);
                assert_eq!(
                    BuffaloZdo::check_status(&case.expected),
                    expected_status == 0,
                    "{}",
                    case.name
                );
            }
            other => panic!("{}: unknown op {other}", case.name),
        }
    }
}

#[test]
fn zdo_bind_payloads_encode_addressing_modes() {
    // Unicast binds carry the destination IEEE and endpoint; multicast binds
    // carry the group id. Both are generated from the pinned oracle above;
    // this test additionally pins the addressing semantics.
    let source = Value::from("0x0017880104e45531");
    let unicast = BuffaloZdo::build_request(
        false,
        ClusterId::BIND_REQUEST,
        &[
            source.clone(),
            Value::from(1),
            Value::from(6),
            Value::from(3),
            Value::from("0x0017880104e45599"),
            Value::Null,
            Value::from(2),
        ],
    );
    assert_eq!(hex(&unicast), "3155e40401881700010600039955e4040188170002");
    let multicast = BuffaloZdo::build_request(
        false,
        ClusterId::BIND_REQUEST,
        &[
            source,
            Value::from(1),
            Value::from(6),
            Value::from(1),
            Value::Null,
            Value::from(0x1234),
            Value::Null,
        ],
    );
    assert_eq!(hex(&multicast), "3155e40401881700010600013412");
}
